import ast
from pathlib import Path
root = Path('products/actors/csv-preflight')
for relative in ('src/core.py', 'tests/run_tests.py'):
    tree = ast.parse((root / relative).read_text(encoding='utf-8'))
    for item in tree.body:
        if isinstance(item, ast.FunctionDef) and (relative.startswith('tests/') or not item.name.startswith('_')):
            print(f'{relative}:{item.lineno} {item.name}({ast.unparse(item.args)})')
            if relative.startswith('tests/'):
                for node in ast.walk(item):
                    if isinstance(node, ast.Assert):
                        print('  assert', ast.unparse(node.test))
